export default {async fetch(req,env){const u=new URL(req.url);if(u.pathname.startsWith('/api/')||u.pathname.startsWith('/media/'))return handleBackend(req,env);if(!['GET','HEAD'].includes(req.method))return new Response('Method not allowed',{status:405});let key=u.pathname.endsWith('/')?u.pathname+'index.html':u.pathname;if(!assets[key]&&assets[key+'/index.html'])return Response.redirect(u.origin+u.pathname+'/',301);const asset=assets[key];if(!asset)return new Response('Page not found',{status:404});const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));return new Response(req.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'SAMEORIGIN'}})}};